/* harmony default export */ __webpack_exports__["default"] = ({
  onLoad(e) {
    this.id = e.id || '';
  },
  onShow() {
    this.getOrdeAfterSale();
  },
  computed: {
    is_disabld() {
      return this.info.expressno != '' && this.info.expressname != '';
    },
    btnStyle() {
      let style = {
        width: '80vw'
      };
      if (!this.is_disabld) {
        style.backgroundColor = this.theme.bgColor;
        style.color = this.theme.color;
      }
      return style;
    }
  },
  data() {
    return {
      show: false,
      info: {},
      goods: {},
      expressname: '',
      expressno: ''
    };
  },
  methods: {
    getOrdeAfterSale() {
      this.$api.ordeAfterSale({
        id: this.id
      }).then(res => {
        if (res.code) {
          this.info = res.data;
          this.goods = res.data.order_goods;
          this.expressname = res.data.expressname;
          this.expressno = res.data.expressno;
        }
        uni.stopPullDownRefresh();
      });
    },
    preview(index) {
      uni.previewImage({
        current: index,
        urls: this.info.images,
        longPressActions: {
          itemList: ['发送给朋友', '保存图片', '收藏'],
          success: function (data) {
            console.log(data);
          },
          fail: function (err) {
            console.log(err.errMsg);
          }
        }
      });
    },
    submit() {
      this.$api.saveExpressInfo({
        expressname: this.expressname,
        expressno: this.expressno,
        id: this.id
      }).then(res => {
        this.$u.toast(res.msg);
        if (res.code) {
          setTimeout(() => {
            this.getOrdeAfterSale();
          }, 1000);
        }
      });
    }
  },
  onPullDownRefresh() {
    this.getOrdeAfterSale();
  }
});

